// Central run configuration. Tune the caps here.
const now = new Date();
const base = {
  organization_locations: ['California, US'],
  organization_num_employees_ranges: ['3,200'],
  per_page: 25,
  page: 1,
};
return [{
  json: {
    monthKey: now.toISOString().slice(0, 7),
    currentYear: now.getFullYear(),
    maxNewPerVertical: 8,
    maxRevealsPerRun: 12,
    monthlyCreditCap: 48,
    verticals: [
      { vertical: 'personal_injury_law', apolloBody: { ...base, q_organization_keyword_tags: ['personal injury law'] } },
      { vertical: 'medical_practice', apolloBody: { ...base, q_organization_keyword_tags: ['dental practice', 'medical clinic', 'med spa'] } },
      { vertical: 'home_services', apolloBody: { ...base, q_organization_keyword_tags: ['plumbing', 'hvac', 'electrical contractor'] } },
    ],
  },
}];

// Sum month-to-date Apollo credits and decide whether the run may proceed.
const config = $('Run Config').first().json;
const mtd = $input.all().reduce((s, i) => s + ((i.json && i.json.credits_used) || 0), 0);
return [{ json: { ...config, mtdCredits: mtd, underBudget: mtd < config.monthlyCreditCap } }];

// One item per vertical, each carrying the Apollo body + the dedup sets.
const cfg = $('Compute Budget').first().json;
const norm = (d) => String(d || '').toLowerCase().replace(/^www\./, '').trim();
const known = new Set(
  $('Get Existing Domains').all().map((i) => norm(i.json && i.json.domain)).filter(Boolean)
);
for (const i of $('Get Suppression List').all()) {
  const d = norm(i.json && i.json.domain);
  if (d) known.add(d);
}
return cfg.verticals.map((v) => ({
  json: {
    vertical: v.vertical,
    apolloBody: v.apolloBody,
    knownDomains: [...known],
    maxNewPerVertical: cfg.maxNewPerVertical,
  },
}));

// Normalize domains, drop already-known/suppressed companies, cap per vertical.
const ctx = $('Per Vertical').first().json;
const norm = (d) => String(d || '').toLowerCase().replace(/^www\./, '').trim();
const known = new Set(ctx.knownDomains);
const seen = new Set();
const out = [];
const orgs = ($input.first().json && $input.first().json.organizations) || [];
for (const org of orgs) {
  const fromUrl = String(org.website_url || '').replace(/^https?:\/\//, '').split('/')[0];
  const domain = norm(org.primary_domain || fromUrl);
  if (!domain || known.has(domain) || seen.has(domain)) continue;
  seen.add(domain);
  out.push({
    json: {
      company_name: org.name,
      domain,
      website_url: org.website_url || 'https://' + domain,
      org_id: org.id,
      employee_count: org.estimated_num_employees ?? null,
      city: org.city || null,
      state: org.state || 'CA',
      phone: org.sanitized_phone || org.phone || null,
      vertical: ctx.vertical,
    },
  });
  if (out.length >= ctx.maxNewPerVertical) break;
}
// Always return at least one item so the Split In Batches loop keeps moving.
return out.length ? out : [{ json: { _empty: true, vertical: ctx.vertical } }];

// Detect AI-adoption signals in the scraped HTML.
const company = $('Per Company').first().json;
const resp = $input.first().json || {};
const html = String(resp.body || '').toLowerCase();
const headers = resp.headers || {};

const MARKERS = {
  chatbot: [
    /widget\.intercom|intercomcdn|\bintercom\b/, /drift\.com|driftt\.com/, /tidio/, /crisp\.chat/,
    /tawk\.to/, /livechatinc|livechat\.com/, /zopim|zendesk[^"']{0,40}(chat|widget)/,
    /hs-chat|hubspot[^"']{0,40}conversations/, /manychat/, /botpress/, /chatbase/, /voiceflow/,
    /podiumwebchat|podium\.com/, /birdeye/,
  ],
  ai_voice: [
    /openai|chatgpt/, /retell\.?ai/, /vapi\.ai/, /synthflow/, /\bair\.ai\b/, /smith\.ai/,
    /elevenlabs/, /\bai (assistant|receptionist|agent|chat)\b/,
  ],
  booking: [
    /calendly/, /acuityscheduling/, /setmore/, /youcanbook/, /squarespacescheduling|squarespace-scheduling/,
    /zocdoc/, /nexhealth/, /localmed/, /jane\.app/, /mindbody/, /vagaro/, /housecallpro/,
    /servicetitan/, /getjobber|jobber\.com/,
  ],
  crm: [
    /hs-scripts|hsforms|hubspot/, /salesforce|pardot/, /\bzoho\b/, /pipedrive/,
    /infusionsoft|keap\.com/, /leadconnectorhq|gohighlevel|highlevel/, /lawmatics/, /cliogrow|clio\.com/,
  ],
  email_mkt: [
    /chimpstatic|list-manage|mailchimp/, /klaviyo/, /constantcontact|ctctcdn/,
    /activehosted|activecampaign/, /sendinblue|brevo/, /convertkit/,
  ],
  forms: [/gravityforms|gform_/, /wpforms/, /typeform/, /jotform/, /formstack/, /<form[^>]*(contact|quote|consult|appointment)/],
  analytics: [/gtag\(|googletagmanager|google-analytics/],
  call_tracking: [/callrail/, /calltrackingmetrics/],
  ad_pixel: [/fbevents\.js|fbq\(/, /adsbygoogle/],
};

const detected = {};
for (const [cat, patterns] of Object.entries(MARKERS)) {
  const hits = patterns.filter((p) => p.test(html)).length;
  if (hits > 0) detected[cat] = hits;
}

const yearMatches = [...html.matchAll(/(?:\u00a9|&copy;|copyright)[^0-9]{0,20}(20\d{2})/g)].map((m) => Number(m[1]));
const copyrightYear = yearMatches.length ? Math.max(...yearMatches) : null;
const lastModified = headers['last-modified'] || null;
const social = {
  facebook: /facebook\.com\//.test(html),
  instagram: /instagram\.com\//.test(html),
  linkedin: /linkedin\.com\/(company|in)\//.test(html),
};

return [{ json: { ...company, detected, copyrightYear, lastModified, social } }];

// Merge BuiltWith tech names into the company item (optional enrichment only).
const base = $('Detect Tech Signals').first().json;
const bw = $input.first().json || {};
const techs = [];
for (const g of bw.groups || []) {
  if (g.name) techs.push(g.name);
  for (const c of g.categories || []) {
    if (c.name) techs.push(c.name);
  }
}
return [{ json: { ...base, builtwith: techs } }];

// Score AI maturity (0 = Tier 1, highest intent) and intent (0-100).
const c = $('Merge Paths').first().json;
const cfg = $('Compute Budget').first().json;
const resp = $input.first().json || {};
const jobs = Array.isArray(resp.organization_job_postings) ? resp.organization_job_postings.length : 0;

const d = c.detected || {};
const coreCats = ['chatbot', 'ai_voice', 'booking', 'crm', 'email_mkt'].filter((k) => d[k]);
let ai = 0;
if (d.chatbot || d.ai_voice || coreCats.length >= 3) ai = 2;
else if (coreCats.length >= 1) ai = 1;

const emp = c.employee_count || 0;
let empPts = 0;
if (emp >= 5 && emp <= 50) empPts = 25;       // sweet spot
else if (emp >= 3 && emp < 5) empPts = 10;
else if (emp > 50 && emp <= 200) empPts = 15;
else if (emp > 200) empPts = 5;

const hiringPts = Math.min(20, jobs * 7);

let freshPts = 0;
if (c.copyrightYear === cfg.currentYear) freshPts = 15;
else if (c.copyrightYear === cfg.currentYear - 1) freshPts = 9;
if (c.lastModified) {
  const ageDays = (Date.now() - new Date(c.lastModified).getTime()) / 86400000;
  if (!Number.isNaN(ageDays) && ageDays <= 90) freshPts = Math.min(20, freshPts + 5);
}

let techPts = 0;
if (d.analytics) techPts += 5;
if (d.call_tracking) techPts += 5;
if (d.ad_pixel) techPts += 5;

const gapPts = ai === 0 ? 20 : ai === 1 ? 10 : 0;

const intent = Math.max(0, Math.min(100, empPts + hiringPts + freshPts + techPts + gapPts));
const qualified = intent >= 40 && emp >= 3;

return [{ json: { ...c, active_job_postings: jobs, ai_maturity_score: ai, intent_score: intent, qualified, scored: true } }];

// Decide which qualified prospects get an Apollo email reveal this run.
// HARD CAP: maxRevealsPerRun (default 12) - the only credit-consuming step.
const cfg = $('Compute Budget').first().json;
const items = $input.all().map((i) => i.json);
const qualified = items.filter((x) => x.qualified).sort((a, b) => b.intent_score - a.intent_score);
const revealSet = new Set(qualified.slice(0, cfg.maxRevealsPerRun).map((x) => x.domain));
return items.map((x) => ({
  json: {
    ...x,
    needsReveal: revealSet.has(x.domain),
    email_pending: !!x.qualified && !revealSet.has(x.domain),
  },
}));

// People search failed permanently for this prospect - keep the row, flag the email as pending.
const company = $('Per Reveal').first().json;
return [{ json: { ...company, email_pending: true, reveal_error: true } }];

// Rank the returned people by title priority and pick the best contact.
const company = $('Per Reveal').first().json;
const people = ($input.first().json && $input.first().json.people) || [];
const priority = ['owner', 'founder', 'managing partner', 'partner', 'ceo', 'president', 'practice manager', 'office manager', 'operations manager'];
const rank = (t) => {
  const title = String(t || '').toLowerCase();
  const i = priority.findIndex((p) => title.includes(p));
  return i === -1 ? priority.length : i;
};
const best = [...people].sort((a, b) => rank(a.title) - rank(b.title))[0];
if (!best) {
  return [{ json: { ...company, contact_found: false, email_pending: true } }];
}
return [{
  json: {
    ...company,
    contact_found: true,
    contact_person_id: best.id,
    contact_name: [best.first_name, best.last_name].filter(Boolean).join(' ') || null,
    contact_title: best.title || null,
  },
}];

// Attach the revealed email/phone to the prospect row.
const company = $('Pick Best Contact').first().json;
const resp = $input.first().json || {};
const person = resp.person || {};
const email = person.email && !String(person.email).includes('email_not_unlocked') ? person.email : null;
return [{
  json: {
    ...company,
    contact_email: email,
    contact_phone: company.phone || person.sanitized_phone || null,
    credit_spent: true,
    email_pending: !email,
  },
}];

// Build the PostgREST upsert payload. NOTE: `tier` is a generated column in
// Postgres and must NOT be included here.
const cfg = $('Compute Budget').first().json;
const items = $input.all().map((i) => i.json).filter((x) => x && x.domain && x.scored);
const rows = items.map((x) => ({
  company_name: x.company_name,
  domain: x.domain,
  website_url: x.website_url || null,
  vertical: x.vertical,
  city: x.city || null,
  state: x.state || 'CA',
  contact_name: x.contact_name || null,
  contact_title: x.contact_title || null,
  contact_email: x.contact_email || null,
  contact_phone: x.contact_phone || x.phone || null,
  employee_count: x.employee_count ?? null,
  ai_maturity_score: x.ai_maturity_score,
  intent_score: x.intent_score,
  signals: {
    detected: x.detected || {},
    builtwith: x.builtwith || [],
    social: x.social || {},
    copyright_year: x.copyrightYear ?? null,
    last_modified: x.lastModified || null,
    active_job_postings: x.active_job_postings ?? 0,
    qualified: !!x.qualified,
    email_pending: !!x.email_pending,
  },
  source: 'apollo',
  last_updated: new Date().toISOString(),
}));
const revealsAttempted = items.filter((x) => x.credit_spent).length;
const counts = {
  scraped: items.length,
  qualified: items.filter((x) => x.qualified).length,
  reveals_attempted: revealsAttempted,
  emails_revealed: items.filter((x) => x.contact_email).length,
  tier1: items.filter((x) => x.ai_maturity_score === 0).length,
  tier2: items.filter((x) => x.ai_maturity_score === 1).length,
  tier3: items.filter((x) => x.ai_maturity_score === 2).length,
};
return [{ json: { rows, revealsAttempted, counts, monthKey: cfg.monthKey } }];
